$ErrorActionPreference='Stop'
$js=@'
const port=17410;
const urls=[
"https://krasnoyarsk.cian.ru/rent/suburban/220035588/",
"https://krasnoyarsk.cian.ru/rent/suburban/324752683/",
"https://krasnoyarsk.cian.ru/rent/suburban/277564646/",
"https://krasnoyarsk.cian.ru/rent/suburban/278639759/",
"https://krasnoyarsk.cian.ru/rent/suburban/297149485/"
];
const info=await (await fetch("http://127.0.0.1:"+port+"/json/version")).json();
const ws=new WebSocket(info.webSocketDebuggerUrl);
await new Promise((resolve,reject)=>{ws.addEventListener("open",resolve,{once:true});ws.addEventListener("error",reject,{once:true})});
let idx=0;const pending=new Map();
ws.addEventListener("message",e=>{try{const x=JSON.parse(e.data);if(x.id&&pending.has(x.id)){const f=pending.get(x.id);pending.delete(x.id);f(x)}}catch{}});
const send=(method,params)=>new Promise((res,rej)=>{const id=++idx;pending.set(id,res);ws.send(JSON.stringify({id,method,params}));setTimeout(()=>{if(pending.has(id)){pending.delete(id);rej(Error("CDP_TIMEOUT"))}},7000)});
let results=[];
for(const url of urls){try{const x=await send("Target.createTarget",{url,background:true,newWindow:false});results.push({url,ok:!!x.result?.targetId,target_id:x.result?.targetId||null});}catch(e){results.push({url,error:String(e).slice(0,60)})}}
ws.close();console.log(JSON.stringify({results}));
'@
$tmp=Join-Path $env:TEMP 'pc-cottage-background-open-20261012b.mjs'
try{[System.IO.File]::WriteAllText($tmp,$js,[System.Text.UTF8Encoding]::new($false));& node.exe $tmp}finally{Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue}
